// tb_vectors.cpp — file-driven testbench: runs the compute kernels on test vectors
// exported from the model (or generated by tools/dsc_vectors.py).
//
//   build/tb_vectors <case_dir> [<case_dir> ...]
//
// Each case is one depthwise-separable block (DW 3x3 -> PW 1x1). File format: see
// VECTORS.md. For each case this checks, in order:
//   1. golden model  vs expected_*.bin (if present): does our arithmetic agree with
//      the model's exported reference outputs? (catches e.g. rounding-mode mismatches
//      between the PyTorch quantization and the hardware)
//   2. depthwise_top vs golden (bit-exact), and the output buffer outside the valid
//      region is untouched
//   3. pointwise_top and pointwise_skip_top (skip on and bypass), fed the kernel's own
//      depthwise output, vs golden (bit-exact); sched_len vs an independent count
// and reports the measured skip rate for the real weights.
//
// Exit code 0 only if every case passes.

#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <string>
#include "dsc_types.h"
#include "dsc_kernels.h"
#include "dsc_golden.h"

static const int SENTINEL = 255;   // no valid activation exceeds ACT_RELU6_MAX = 192

// ---- buffers -------------------------------------------------------------------------
static int   g_in[DW_C][DW_H][DW_W], g_dw_wt[DW_C][DW_K][DW_K], g_dw_b[DW_C];
static int   g_pw_wt[PW_C_OUT][PW_C_IN], g_pw_b[PW_C_OUT];
static int   g_dw_out[DW_C][DW_HO_MAX][DW_WO_MAX], g_pw_out[PW_C_OUT][PW_H][PW_W];
static uint8_t e_dw[DW_C * DW_HO_MAX * DW_WO_MAX], e_pw[PW_C_OUT * PW_H * PW_W];

static act_t k_in[DW_C][DW_H][DW_W];
static wgt_t k_dw_wt[DW_C][DW_K][DW_K], k_pw_wt[PW_C_OUT][PW_C_IN];
static acc_t k_dw_b[DW_C], k_pw_b[PW_C_OUT];
static act_t k_dw_out[DW_C][DW_HO_MAX][DW_WO_MAX];
static act_t k_pw_in[PW_C_IN][PW_H][PW_W];
static act_t k_pw_out[PW_C_OUT][PW_H][PW_W];

// ---- file helpers ----------------------------------------------------------------------
// Reads exactly `bytes` bytes. Returns 1 on success, 0 if the file is missing
// (allowed only when !required), -1 on a size mismatch or read error.
static int read_exact(const std::string& path, void* dst, long bytes, bool required, std::string& err) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) {
        if (required) err = "missing " + path;
        return required ? -1 : 0;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz != bytes) {
        char buf[256];
        snprintf(buf, sizeof buf, "%s: %ld bytes, expected %ld", path.c_str(), sz, bytes);
        err = buf;
        fclose(f);
        return -1;
    }
    size_t n = fread(dst, 1, (size_t)bytes, f);
    fclose(f);
    if ((long)n != bytes) { err = "short read on " + path; return -1; }
    return 1;
}

struct Meta { int format_version = -1, stride = -1, c = -1, h = -1, w = -1, c_out = -1; };

static bool read_meta(const std::string& dir, Meta& m, std::string& err) {
    FILE* f = fopen((dir + "/meta.txt").c_str(), "r");
    if (!f) { err = "missing " + dir + "/meta.txt"; return false; }
    char line[256];
    while (fgets(line, sizeof line, f)) {
        char* hash = strchr(line, '#');
        if (hash) *hash = 0;
        char key[64]; int val;
        if (sscanf(line, "%63s %d", key, &val) != 2) continue;
        if      (!strcmp(key, "format_version")) m.format_version = val;
        else if (!strcmp(key, "stride")) m.stride = val;
        else if (!strcmp(key, "c"))      m.c = val;
        else if (!strcmp(key, "h"))      m.h = val;
        else if (!strcmp(key, "w"))      m.w = val;
        else if (!strcmp(key, "c_out"))  m.c_out = val;
    }
    fclose(f);
    if (m.format_version != 1) { err = "meta.txt: format_version must be 1"; return false; }
    if (m.stride != 1 && m.stride != 2) { err = "meta.txt: stride must be 1 or 2"; return false; }
    if (m.c != DW_C || m.h != DW_H || m.w != DW_W || m.c_out != PW_C_OUT) {
        char buf[256];
        snprintf(buf, sizeof buf, "dims %dx%dx%d -> %d don't match the hardware build %dx%dx%d -> %d",
                 m.c, m.h, m.w, m.c_out, DW_C, DW_H, DW_W, PW_C_OUT);
        err = buf;
        return false;
    }
    return true;
}

static int32_t le32(const uint8_t* p) {
    return (int32_t)((uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24));
}

// Loads all input files into the golden (int) and kernel arrays. Returns false on error.
static bool load_case(const std::string& dir, const Meta& m, bool& have_e_dw, bool& have_e_pw,
                      std::string& err) {
    static uint8_t in8[DW_C * DW_H * DW_W], dwwt8[DW_C * 9], pwwt8[PW_C_OUT * PW_C_IN];
    static uint8_t dwb[DW_C * 4], pwb[PW_C_OUT * 4];
    const int ho = (DW_H + 2 * DW_PAD - DW_K) / m.stride + 1;
    const int wo = (DW_W + 2 * DW_PAD - DW_K) / m.stride + 1;
    if (read_exact(dir + "/dw_in.bin", in8, sizeof in8, true, err) < 0) return false;
    if (read_exact(dir + "/dw_wt.bin", dwwt8, sizeof dwwt8, true, err) < 0) return false;
    if (read_exact(dir + "/dw_b.bin", dwb, sizeof dwb, true, err) < 0) return false;
    if (read_exact(dir + "/pw_wt.bin", pwwt8, sizeof pwwt8, true, err) < 0) return false;
    if (read_exact(dir + "/pw_b.bin", pwb, sizeof pwb, true, err) < 0) return false;
    int r;
    if ((r = read_exact(dir + "/expected_dw_out.bin", e_dw, (long)DW_C * ho * wo, false, err)) < 0) return false;
    have_e_dw = (r == 1);
    if ((r = read_exact(dir + "/expected_pw_out.bin", e_pw, (long)PW_C_OUT * ho * wo, false, err)) < 0) return false;
    have_e_pw = (r == 1);

    for (int c = 0; c < DW_C; c++) {
        for (int y = 0; y < DW_H; y++)
            for (int x = 0; x < DW_W; x++) {
                g_in[c][y][x] = in8[(c * DW_H + y) * DW_W + x];
                k_in[c][y][x] = (act_t)g_in[c][y][x];
            }
        for (int ky = 0; ky < 3; ky++)
            for (int kx = 0; kx < 3; kx++) {
                g_dw_wt[c][ky][kx] = (int8_t)dwwt8[c * 9 + ky * 3 + kx];
                k_dw_wt[c][ky][kx] = (wgt_t)g_dw_wt[c][ky][kx];
            }
        g_dw_b[c] = le32(dwb + 4 * c);
        k_dw_b[c] = (acc_t)g_dw_b[c];
    }
    for (int k = 0; k < PW_C_OUT; k++) {
        for (int c = 0; c < PW_C_IN; c++) {
            g_pw_wt[k][c] = (int8_t)pwwt8[k * PW_C_IN + c];
            k_pw_wt[k][c] = (wgt_t)g_pw_wt[k][c];
        }
        g_pw_b[k] = le32(pwb + 4 * k);
        k_pw_b[k] = (acc_t)g_pw_b[k];
    }
    for (int i = 0; i < DW_C; i++)
        if (g_dw_b[i] > BIAS_ABS_MAX || g_dw_b[i] < -BIAS_ABS_MAX) { err = "dw_b.bin: bias exceeds BIAS_ABS_MAX"; return false; }
    for (int i = 0; i < PW_C_OUT; i++)
        if (g_pw_b[i] > BIAS_ABS_MAX || g_pw_b[i] < -BIAS_ABS_MAX) { err = "pw_b.bin: bias exceeds BIAS_ABS_MAX"; return false; }
    return true;
}

// ---- comparisons -------------------------------------------------------------------------
// Whole-array compare: [0,h) x [0,w) must equal ref, everything else must be SENTINEL.
template <int C, int H, int W>
static int compare_out(const int ref[C][H][W], const act_t k[C][H][W], int h, int w, const char* what) {
    int mism = 0;
    for (int c = 0; c < C; c++)
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++) {
                const bool valid = y < h && x < w;
                const int want = valid ? ref[c][y][x] : SENTINEL, got = (int)k[c][y][x];
                if (want != got) {
                    if (mism < 3)
                        printf("     %s mismatch c=%d y=%d x=%d %s=%d kernel=%d\n", what, c, y, x,
                               valid ? "golden" : "untouched", want, got);
                    mism++;
                }
            }
    return mism;
}

// Golden (int) vs an expected file in C x ho x wo order. Returns mismatches.
template <int C, int H, int W>
static int compare_expected(const int g[C][H][W], const uint8_t* e, int ho, int wo, const char* what,
                            int* max_diff) {
    int mism = 0;
    *max_diff = 0;
    for (int c = 0; c < C; c++)
        for (int y = 0; y < ho; y++)
            for (int x = 0; x < wo; x++) {
                const int ev = e[(c * ho + y) * wo + x], gv = g[c][y][x];
                if (ev != gv) {
                    if (mism < 3) printf("     %s c=%d y=%d x=%d expected=%d golden=%d\n", what, c, y, x, ev, gv);
                    int d = ev > gv ? ev - gv : gv - ev;
                    if (d > *max_diff) *max_diff = d;
                    mism++;
                }
            }
    return mism;
}

static int expected_sched_len() {
    int total = 0;
    for (int k = 0; k < PW_C_OUT; k++) {
        int nz = 0;
        for (int cb = 0; cb < PW_CBLKS; cb++) {
            bool any = false;
            for (int u = 0; u < PW_UNROLL; u++) any |= (g_pw_wt[k][cb * PW_UNROLL + u] != 0);
            nz += any;
        }
        total += nz > 0 ? nz : 1;
    }
    return total;
}

// ---- one case -----------------------------------------------------------------------------
static bool run_case(const std::string& dir) {
    printf("== %s\n", dir.c_str());
    Meta m;
    std::string err;
    bool have_e_dw = false, have_e_pw = false;
    if (!read_meta(dir, m, err) || !load_case(dir, m, have_e_dw, have_e_pw, err)) {
        printf("   [FAIL] %s\n", err.c_str());
        return false;
    }
    const int ho = (DW_H + 2 * DW_PAD - DW_K) / m.stride + 1;
    const int wo = (DW_W + 2 * DW_PAD - DW_K) / m.stride + 1;
    bool ok = true;

    // 1. golden vs the model's expected outputs
    golden_depthwise(g_in, g_dw_wt, g_dw_b, m.stride, g_dw_out);
    static int g_pw_in[PW_C_IN][PW_H][PW_W];
    for (int c = 0; c < PW_C_IN; c++)
        for (int y = 0; y < PW_H; y++)
            for (int x = 0; x < PW_W; x++)
                g_pw_in[c][y][x] = (y < ho && x < wo) ? g_dw_out[c][y][x] : 0;
    golden_pointwise(g_pw_in, g_pw_wt, g_pw_b, ho, wo, g_pw_out);
    const struct { bool have; const char* name; } exps[2] = {{have_e_dw, "expected_dw_out"},
                                                             {have_e_pw, "expected_pw_out"}};
    for (int i = 0; i < 2; i++) {
        if (!exps[i].have) { printf("   [----] golden vs %s.bin: not present\n", exps[i].name); continue; }
        int maxd = 0;
        const int bad = (i == 0)
            ? compare_expected<DW_C, DW_HO_MAX, DW_WO_MAX>(g_dw_out, e_dw, ho, wo, exps[i].name, &maxd)
            : compare_expected<PW_C_OUT, PW_H, PW_W>(g_pw_out, e_pw, ho, wo, exps[i].name, &maxd);
        printf("   [%s] golden vs %s.bin: %d mismatches%s\n", bad ? "FAIL" : "PASS", exps[i].name, bad,
               (bad && maxd == 1) ? " (all +/-1: likely a rounding-mode mismatch, see VECTORS.md)" : "");
        ok &= (bad == 0);
    }

    // 2. depthwise kernel vs golden
    for (int c = 0; c < DW_C; c++)
        for (int y = 0; y < DW_HO_MAX; y++)
            for (int x = 0; x < DW_WO_MAX; x++) k_dw_out[c][y][x] = (act_t)SENTINEL;
    depthwise_top(k_in, k_dw_wt, k_dw_b, m.stride, k_dw_out);
    int bad = compare_out<DW_C, DW_HO_MAX, DW_WO_MAX>(g_dw_out, k_dw_out, ho, wo, "depthwise");
    printf("   [%s] depthwise_top vs golden: %d mismatches\n", bad ? "FAIL" : "PASS", bad);
    ok &= (bad == 0);

    // 3. pointwise kernels, fed the depthwise kernel's own output
    for (int c = 0; c < PW_C_IN; c++)
        for (int y = 0; y < PW_H; y++)
            for (int x = 0; x < PW_W; x++)
                k_pw_in[c][y][x] = (y < ho && x < wo) ? k_dw_out[c][y][x] : (act_t)0;
    for (int k = 0; k < PW_C_OUT; k++)
        for (int y = 0; y < PW_H; y++)
            for (int x = 0; x < PW_W; x++) k_pw_out[k][y][x] = (act_t)SENTINEL;
    pointwise_top(k_pw_in, k_pw_wt, k_pw_b, ho, wo, k_pw_out);
    bad = compare_out<PW_C_OUT, PW_H, PW_W>(g_pw_out, k_pw_out, ho, wo, "pointwise");
    printf("   [%s] pointwise_top vs golden: %d mismatches\n", bad ? "FAIL" : "PASS", bad);
    ok &= (bad == 0);

    const int dense_len = PW_C_OUT * PW_CBLKS, exp_len = expected_sched_len();
    int len_skip = -1;
    for (int pass = 0; pass < 2; pass++) {
        const bool skip_en = (pass == 0);
        int len = -1;
        for (int k = 0; k < PW_C_OUT; k++)
            for (int y = 0; y < PW_H; y++)
                for (int x = 0; x < PW_W; x++) k_pw_out[k][y][x] = (act_t)SENTINEL;
        pointwise_skip_top(k_pw_in, k_pw_wt, k_pw_b, ho, wo, skip_en, k_pw_out, len);
        bad = compare_out<PW_C_OUT, PW_H, PW_W>(g_pw_out, k_pw_out, ho, wo,
                                                skip_en ? "skip on" : "bypass");
        const int want_len = skip_en ? exp_len : dense_len;
        const bool len_ok = (len == want_len);
        printf("   [%s] pointwise_skip_top %-8s vs golden: %d mismatches, sched_len %d%s\n",
               (bad || !len_ok) ? "FAIL" : "PASS", skip_en ? "skip on" : "bypass", bad, len,
               len_ok ? "" : " (WRONG)");
        ok &= (bad == 0) && len_ok;
        if (skip_en) len_skip = len;
    }

    int zero_w = 0;
    for (int k = 0; k < PW_C_OUT; k++)
        for (int c = 0; c < PW_C_IN; c++) zero_w += (g_pw_wt[k][c] == 0);
    printf("   pointwise weights zero %.1f%% | cycles/pixel %d of %d | MAC cycles skipped %.1f%%\n",
           100.0 * zero_w / (PW_C_OUT * PW_C_IN), len_skip, dense_len,
           100.0 * (dense_len - len_skip) / dense_len);
    printf("   %s\n", ok ? "CASE PASSED" : "CASE FAILED");
    return ok;
}

int main(int argc, char** argv) {
    // The bias files are little-endian; le32() handles that on any host.
    if (argc < 2) {
        printf("usage: %s <case_dir> [<case_dir> ...]   (format: VECTORS.md)\n", argv[0]);
        return 2;
    }
    int failed = 0;
    for (int i = 1; i < argc; i++) failed += !run_case(argv[i]);
    printf("\n%s: %d of %d case(s) passed\n", failed ? "VECTORS FAILED" : "VECTORS PASSED",
           argc - 1 - failed, argc - 1);
    return failed ? 1 : 0;
}
